// Stand-in for the real IIFE (T-40): records when it ran and every error it sees.
(function () {
  var s = document.currentScript; window.__rp = { initAt: performance.now(), dsn: s && s.getAttribute('data-dsn'), errors: [] };
  addEventListener('error', function (e) { window.__rp.errors.push({ msg: e.message, at: performance.now() }); }, true);
  addEventListener('unhandledrejection', function (e) { window.__rp.errors.push({ msg: String(e.reason), at: performance.now() }); });
})();
